ScoreResult:
  type: object
  description: "Calculated, read-only (REQ-PB-047). weightedScore is the exact stored 1-5 value; display100 = (score-1)/4*100 (REQ-S09-001); incomplete -> both null."
  required: [weightSetVersionNo, completeness, weightedScore, weightedScoreDisplay, display100, conversion, missingCriteria, computedAt]
  additionalProperties: false
  properties:
    weightSetVersionNo: { type: integer, minimum: 1 }
    completeness: { type: string, enum: [complete, incomplete] }
    weightedScore: { $ref: "#/components/schemas/NullableDecimal" }
    weightedScoreDisplay: { type: [string, "null"], description: "Two fraction digits, ROUND_HALF_UP, e.g. 3.30." }
    display100: { type: [string, "null"], description: "0-100 view, at most two fraction digits, trailing zeros removed, e.g. 57.5." }
    conversion: { type: string, enum: ["(score-1)/4*100"] }
    missingCriteria: { type: array, items: { $ref: "#/components/schemas/CriterionCode" } }
