// Problem translations of P6 slices E, F, J and C (T-DG6-FE-A; p6-work-split §E/F.12, §J/C.13, §2 rules 6 and 17). The
// problem `code` is the i18n key (ADR-0007), translated at render time in English and Arabic:
//  - every refusal code of the slice ADRs' tables (ADR-0051 §2, ADR-0052 §1, ADR-0053 §2, ADR-0054 §4), read from the
//    ADR files themselves (indented rows and the "job error" rows included), so a new row cannot go untranslated, plus
//    the two codes the ADRs state in prose (ADR-0051 §3 `deep_link.forbidden`, §4 `evidence.parent_forbidden`) and
//    ADR-0052 §2 `evidence.preview_unavailable`;
//  - the English text is exactly the ADR's English text (rule 17). Three ADR-0052 §1 texts carry a value
//    ({allowedTypes}, {extension}, {maxBytes}) that the contract does not send as problem `params` at this revision, so
//    the problem renders the ADR sentence without that clause (never a raw placeholder), and the `<key>_detail` text is
//    the ADR sentence with the value, for a screen that knows it (the upload policy, the chosen file);
//  - the Arabic text is Arabic and differs from the English. ADR-0053 §2 and ADR-0054 §4 give the Arabic: it is used
//    exactly. ALL the Arabic of the P6 blocks is PROVISIONAL and awaits a Mobily language review: the ADR-0053/0054
//    Arabic (the ADRs label it so), and the Arabic of ADR-0051, ADR-0052, `access.includesRestrictedRecords`,
//    `inbox.restricted` (D-196 item 5) and the nav texts (written by FE-A). The label is i18n/provisional-ar-p6.ts,
//    which a test below binds to the catalogue and to the ADR tables.
// Shared codes in the tables (`invalid_transition`, `not_found`, `forbidden`) keep their existing generic texts.
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { describe, expect, it } from "vitest";
import { problemText } from "../lib/problem.ts";
import { renderMessage } from "../pages/my-work/messages.ts";
import { catalogues, createI18n } from "./index.ts";
import { P6_PROVISIONAL_ARABIC } from "./provisional-ar-p6.ts";

function repoRoot(): string {
  for (let dir = process.cwd(); ; dir = dirname(dir)) {
    if (existsSync(join(dir, "pnpm-workspace.yaml"))) return dir;
    if (dirname(dir) === dir) throw new Error("repository root not found");
  }
}

const P6_SLICE_ADRS = ["0051", "0052", "0053", "0054"];
/** `| 4xx | \`code\` | "English" |` or `| job error | \`code\` | "English" | "Arabic" |`, optionally indented. */
const ROW = /^\s*\|\s*(?:4\d\d|job error)\s*\|\s*`([a-z_][a-z0-9_.]*)`\s*\|\s*(.*?)\s*\|(?:\s*(.*?)\s*\|)?\s*$/;
const SHARED = new Set(["invalid_transition", "not_found", "forbidden"]);

function adrText(n: string): string {
  const dir = join(repoRoot(), "docs", "architecture", "adr");
  const file = readdirSync(dir).find((f) => f.startsWith(`ADR-${n}-`));
  if (!file) throw new Error(`ADR-${n} not found`);
// Problem translations of slices H, I, C, A, J and K (T-DG4-FE-R1; S-6, S-11). The problem `code` is the i18n key
// (ADR-0007), translated at render time in English and Arabic:
//  - every refusal code of the slice ADRs' tables (ADR-0025 to ADR-0028: slices I, C and A; ADR-0035, ADR-0036: slice H;
//    ADR-0037: slice J; ADR-0038: slice K), read from the ADR files themselves, so a new row cannot go untranslated;
//  - the ARCH-R1/R2 code-table codes of those slices, named by the assignment (approval.resubmit_through_record,
//    gate.exception_revoked, gate.modular_links_missing, the gate.modular_waiver_* codes) and the 422 error items;
//  - a problem message is rendered without parameters, so no text keeps a server placeholder such as {date}; the only
//    texts with a placeholder are the two codes that carry `params` (ADR-0038 Q1: `gate.modular_waiver_revoked` and
//    `gate.modular_waiver_expired`, `{{date}}`), rendered here with their `params` and, without them, as before.
// T-DG4-FE-R3 (ARCH-R3 §6 FE-R3 item 4, §7): the ADR scan reads BOTH table formats, the original `| 4xx | \`code\` |`
// rows and the amendment rows `| \`code\` (at …) | 4xx | …` (every ARCH-R1/R2/R3 amendment table). The original scan
// missed the amendment format, e.g. ADR-0037 row `dashboard.value_class_not_applicable` (requirements row 186); a test
// below proves the new scan finds it and that the old one did not.
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import type { TFunction } from "i18next";
import { describe, expect, it } from "vitest";
import { formatBusinessDate } from "../lib/format.ts";
import { problemText } from "../lib/problem.ts";
import { createI18n } from "./index.ts";

function repoRoot(): string {
  for (let dir = process.cwd(); ; dir = dirname(dir)) {
    if (existsSync(join(dir, "pnpm-workspace.yaml"))) return dir;
    if (dirname(dir) === dir) throw new Error("repository root not found");
  }
}

const SLICE_ADRS = ["0025", "0026", "0027", "0028", "0035", "0036", "0037", "0038"];

